.cta .container{position:relative;z-index:1}.cta h2{letter-spacing:-.07em;font-size:clamp(59px,6.2vw,92px)}
.footer{background:#042d25}.footer-grid{padding:74px 0 65px}.foot-bottom{border-color:#d8f9e518}
